create extension if not exists pgcrypto;
create type public.app_role as enum ('platform_admin','clinic_owner','receptionist');
create type public.clinic_status as enum ('pending_approval','active','rejected','suspended');
create type public.visit_status as enum ('waiting','called','consulting','completed','cancelled','no_show','skipped');
create table public.clinics (id uuid primary key default gen_random_uuid(), name text not null, owner_user_id uuid references auth.users(id), address text, phone text, consultation_fee numeric(10,2) not null default 300, status public.clinic_status not null default 'pending_approval', qr_identifier text unique not null default encode(gen_random_bytes(8),'hex'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, name text not null, role public.app_role not null, clinic_id uuid references public.clinics(id), created_at timestamptz not null default now());
create table public.patients (id uuid primary key default gen_random_uuid(), clinic_id uuid not null references public.clinics(id) on delete cascade, name text not null, age integer not null check (age between 0 and 130), phone text not null, created_at timestamptz not null default now());
create table public.visits (id uuid primary key default gen_random_uuid(), clinic_id uuid not null references public.clinics(id) on delete cascade, patient_id uuid not null references public.patients(id), doctor_id uuid references auth.users(id), visit_date date not null default current_date, token_number integer not null, status public.visit_status not null default 'waiting', called_at timestamptz, consultation_started_at timestamptz, consultation_finished_at timestamptz, consultation_duration integer, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index visits_daily_token on public.visits(clinic_id, visit_date, token_number);
create table public.queue_status (clinic_id uuid primary key references public.clinics(id) on delete cascade, is_paused boolean not null default false, pause_reason text, updated_at timestamptz not null default now());
create table public.billing_usage (id uuid primary key default gen_random_uuid(), visit_id uuid unique not null references public.visits(id), clinic_id uuid not null references public.clinics(id), amount numeric(10,2) not null, usage_date date not null default current_date, created_at timestamptz not null default now());
create table public.platform_settings (id boolean primary key default true, price_per_completed numeric(10,2) not null default 2.50, monthly_cap numeric(10,2) not null default 5000, updated_at timestamptz not null default now());
insert into public.platform_settings default values on conflict do nothing;
create or replace function public.is_clinic_member(target_clinic uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.profiles where id = auth.uid() and clinic_id = target_clinic); $$;
create or replace function public.join_clinic_queue(qr_code text, patient_name text, patient_age integer, patient_phone text) returns public.visits language plpgsql security definer set search_path = public as $$ declare c public.clinics; p public.patients; v public.visits; next_token integer; begin select * into c from public.clinics where qr_identifier = qr_code and status = 'active'; if c.id is null then raise exception 'Clinic is not active or QR is invalid'; end if; insert into public.patients(clinic_id,name,age,phone) values(c.id,trim(patient_name),patient_age,trim(patient_phone)) returning * into p; select coalesce(max(token_number),0)+1 into next_token from public.visits where clinic_id=c.id and visit_date=current_date; insert into public.visits(clinic_id,patient_id,doctor_id,token_number) values(c.id,p.id,c.owner_user_id,next_token) returning * into v; return v; end; $$;
alter table public.clinics enable row level security; alter table public.profiles enable row level security; alter table public.patients enable row level security; alter table public.visits enable row level security; alter table public.queue_status enable row level security; alter table public.billing_usage enable row level security; alter table public.platform_settings enable row level security;
create policy clinic_member_clinics on public.clinics for select using (public.is_clinic_member(id) or exists(select 1 from public.profiles where id=auth.uid() and role='platform_admin'));
create policy own_profile on public.profiles for select using (id=auth.uid() or role='platform_admin');
create policy clinic_member_patients on public.patients for all using (public.is_clinic_member(clinic_id));
create policy clinic_member_visits on public.visits for all using (public.is_clinic_member(clinic_id));
create policy clinic_member_queue on public.queue_status for all using (public.is_clinic_member(clinic_id));
create policy clinic_member_billing on public.billing_usage for select using (public.is_clinic_member(clinic_id) or exists(select 1 from public.profiles where id=auth.uid() and role='platform_admin'));
create policy platform_settings_admin on public.platform_settings for all using (exists(select 1 from public.profiles where id=auth.uid() and role='platform_admin'));
alter publication supabase_realtime add table public.visits;
alter publication supabase_realtime add table public.queue_status;